const parseCSV = (text) => {
  const rows = []; let row = []; let cell = ""; let quoted = false;
  for (let i = 0; i < text.length; i += 1) { const char = text[i]; const next = text[i + 1];
    if (char === '"' && quoted && next === '"') { cell += '"'; i += 1; } else if (char === '"') quoted = !quoted;
    else if (char === "," && !quoted) { row.push(cell.trim()); cell = ""; } else if ((char === "\n" || char === "\r") && !quoted) { if (char === "\r" && next === "\n") i += 1; row.push(cell.trim()); if (row.some(Boolean)) rows.push(row); row = []; cell = ""; } else cell += char;
  }
  if (cell || row.length) { row.push(cell.trim()); rows.push(row); }
  const headers = rows.shift()?.map((h) => h.replace(/^"|"$/g, "")) || [];
  return rows.map((values) => headers.reduce((item, key, index) => ({ ...item, [key]: values[index] || "" }), {}));
};

const number = (value) => Number(String(value || 0).replace(/[^0-9.-]/g, "")) || 0;
const rupees = (value) => new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0 }).format(number(value));
const status = (value) => { const s = String(value || "Open").trim().toLowerCase(); return s === "fullfilled" ? "fulfilled" : s; };
const amountOf = (need) => number(need.Amount ?? need.Target_Amount);
const category = (need) => { const text = `${need.Need_Title} ${need.Description}`.toLowerCase(); if (/school|book|education|uniform|stationery|tuition|notebook/.test(text)) return "Education"; if (/meal|food|rice|grocer|kitchen|snack|vegetable|fruits?|provisions?/.test(text)) return "Food"; if (/cloth|shoe|dress|apparel|sandal|socks|jacket|sweater/.test(text)) return "Clothing"; if (/repair|roof|toilet|building|infrastructure|bed|mattress|blanket|table|furniture|dormitory|pillow|cot|fan|light/.test(text)) return "Infrastructure"; return "Other"; };
const computeStats = (needs) => ({ homes: new Set(needs.map((n) => n.Home_Name)).size, open: needs.filter((n) => status(n.Status) === "open").length, sponsored: needs.filter((n) => status(n.Status) === "sponsored").length, fulfilled: needs.filter((n) => status(n.Status) === "fulfilled").length, value: needs.filter((n) => status(n.Status) === "fulfilled").reduce((sum, n) => sum + amountOf(n), 0) });
const fulfilledOf = (needs) => needs.filter((n) => status(n.Status) === "fulfilled");
const childCount = (need) => { const match = `${need.Need_Title} ${need.Description}`.match(/\d+/); return match ? number(match[0]) : 0; };
const childrenBenefited = (needs) => fulfilledOf(needs).reduce((sum, n) => sum + childCount(n), 0);

