const SiteCtx = createContext(null);
const useSite = () => useContext(SiteCtx);
const homePath = (name) => `/homes/${encodeURIComponent(name)}`;

const IconFlow = ({ icon: Icon, label, accent = "orange" }) => <div className={`flow-node ${accent}`}><span className="flow-icon"><Icon size={20} /></span><span>{label}</span></div>;

const useCountUp = (target) => {
  const ref = useRef(null); const [value, setValue] = useState(0);
  useEffect(() => { const el = ref.current; if (!el) return undefined;
    let started = false;
    const run = () => { started = true; const start = performance.now(); const duration = 1200;
      const tick = (now) => { const p = Math.min(1, (now - start) / duration); setValue(Math.round(target * (1 - (1 - p) ** 3))); if (p < 1) requestAnimationFrame(tick); };
      requestAnimationFrame(tick);
    };
    const fallback = setTimeout(() => { if (!started) setValue(target); }, 2500);
    const observer = new IntersectionObserver(([entry]) => { if (!entry.isIntersecting || started) return; observer.disconnect(); clearTimeout(fallback); run(); }, { threshold: 0.35 });
    observer.observe(el); return () => { observer.disconnect(); clearTimeout(fallback); };
  }, [target]);
  return [ref, value];
};

const submitSponsorship = async (event, need, setFormState) => {
  event.preventDefault(); setFormState("loading");
  const form = new FormData(event.currentTarget);
  const payload = { Need_id: need.Need_id, Sponsor_Name: form.get("name"), Sponsor_Contact: form.get("contact"), Message: form.get("message") };
  try { const response = await fetch(WEBHOOK_URL, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }); if (!response.ok) throw new Error("Submission failed"); setFormState("success"); } catch { setFormState("error"); }
};

function App() {
  const [needs, setNeeds] = useState([]); const [loadState, setLoadState] = useState("loading");
  const [lang, setLang] = useState(() => localStorage.getItem("san-lang") || "en");
  const t = COPY[lang] || COPY.en;
  const switchLang = (next) => { setLang(next); localStorage.setItem("san-lang", next); };
  useEffect(() => { fetch(`${SHEET_URL}&_ts=${Date.now()}`, { cache: "no-store" }).then((response) => { if (!response.ok) throw new Error("CSV error"); return response.text(); }).then((text) => { const valid = parseCSV(text).filter((item) => item.Need_id && item.Home_Name && item.Need_Title); setNeeds(valid); setLoadState("ready"); }).catch(() => setLoadState("error")); }, []);
  const value = useMemo(() => ({ needs, loadState, t, lang, switchLang }), [needs, loadState, t, lang]);
  return <SiteCtx.Provider value={value}><BrowserRouter><Routes><Route element={<Layout />}>
    <Route path="/" element={<HomePage />} />
    <Route path="/explore-needs" element={<ExplorePage />} />
    <Route path="/needs/:needId" element={<NeedDetailsPage />} />
    <Route path="/why-we-exist" element={<WhyPage />} />
    <Route path="/how-it-works" element={<HowPage />} />
    <Route path="/our-impact" element={<ImpactPage />} />
    <Route path="/track-my-sponsorships" element={<TrackPage />} />
    <Route path="/homes/:homeName" element={<ChildrenHomePage />} />
    <Route path="*" element={<HomePage />} />
  </Route></Routes></BrowserRouter></SiteCtx.Provider>;
}

function Layout() {
  const { t, lang, switchLang } = useSite();
  const [mobileOpen, setMobileOpen] = useState(false);
  const location = useLocation();
  useEffect(() => { window.scrollTo(0, 0); setMobileOpen(false); }, [location.pathname]);
  const links = [["/", t.nav.home, "nav-home-link"], ["/explore-needs", t.nav.explore, "nav-explore-link"], ["/why-we-exist", t.nav.why, "nav-why-link"], ["/how-it-works", t.nav.how, "nav-how-link"], ["/our-impact", t.nav.impact, "nav-impact-link"], ["/track-my-sponsorships", t.nav.track, "nav-track-link"]];
  return <div className="site-shell" data-testid="sponsor-a-need-app">
    <nav className="nav" data-testid="main-navigation"><Link to="/" className="brand" data-testid="brand-home-link"><span className="brand-mark"><HandHeart size={18} /></span><span>Sponsor <em>a</em> Need</span></Link><button className="mobile-menu" onClick={() => setMobileOpen(!mobileOpen)} aria-label="Open menu" data-testid="mobile-menu-button">{mobileOpen ? <X /> : <Menu />}</button><div className={`nav-links ${mobileOpen ? "open" : ""}`}>{links.map(([to, label, id]) => <NavLink key={to} to={to} end={to === "/"} className={({ isActive }) => `nav-link ${isActive ? "active" : ""}`} data-testid={id}>{label}</NavLink>)}<div className="lang-toggle" data-testid="language-toggle"><button className={lang === "en" ? "active" : ""} onClick={() => switchLang("en")} data-testid="language-toggle-english">{COPY.en.lang.en}</button><button className={lang === "te" ? "active" : ""} onClick={() => switchLang("te")} data-testid="language-toggle-telugu">{COPY.en.lang.te}</button></div><Link to="/explore-needs" className="nav-cta" data-testid="nav-sponsor-button">{t.nav.cta} <ArrowRight size={15} /></Link></div></nav>
    <main key={location.pathname} className="page-fade"><Outlet /></main>
    <footer data-testid="site-footer"><div className="footer-brand"><Link to="/" className="brand" data-testid="footer-brand-link"><span className="brand-mark"><HandHeart size={18} /></span><span>Sponsor <em>a</em> Need</span></Link><p>{t.footer.tag1}<br />{t.footer.tag2}</p></div><div className="footer-links">{links.map(([to, label, id]) => <Link key={to} to={to} data-testid={id.replace("nav-", "footer-")}>{label}</Link>)}</div><p className="footer-note">{t.footer.note}</p></footer>
  </div>;
}

